using System.Numerics;
using System.Runtime.InteropServices;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements using SIMD vectorization.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count * 2)
        {
            var vecs = MemoryMarshal.Cast<float, Vector<float>>(values);

            // Two accumulators to hide multiply latency
            var acc0 = vecs[0];
            var acc1 = Vector<float>.One;

            int j = 1;
            int end = vecs.Length - 1;
            for (; j <= end; j += 2)
            {
                acc0 *= vecs[j];
                if (j + 1 <= end)
                    acc1 *= vecs[j + 1];
            }

            acc0 *= acc1;

            // Horizontal reduce the vector
            float product = 1f;
            for (int k = 0; k < Vector<float>.Count; k++)
                product *= acc0[k];

            i = vecs.Length * Vector<float>.Count;

            // Scalar tail
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4-way unroll
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int limit = values.Length - 3;
        for (; i < limit; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        for (; i < values.Length; i++)
            p0 *= values[i];

        return p0 * p1 * p2 * p3;
    }
}

